package com.dsa.algorithms.dynamicprogramming;
/** Fibonacci implementations demonstrating recursion and dynamic programming. */
public final class Fibonacci {private Fibonacci(){} /** O(n) time and O(1) extra space. */ public static long iterative(int n){if(n<0)throw new IllegalArgumentException("n must be non-negative");long a=0,b=1;for(int i=0;i<n;i++){long next=Math.addExact(a,b);a=b;b=next;}return a;} /** O(n) time and O(n) space; detects long overflow. */ public static long memoized(int n){if(n<0)throw new IllegalArgumentException("n must be non-negative");long[] memo=new long[n+1];java.util.Arrays.fill(memo,-1);return fib(n,memo);}private static long fib(int n,long[] memo){if(n<2)return n;if(memo[n]>=0)return memo[n];memo[n]=Math.addExact(fib(n-1,memo),fib(n-2,memo));return memo[n];}}
